func (a *analyzer) walkStmt(s ast.Stmt, env *pathEnv) bool {
	if s == nil {
		return false
	}
	switch t := s.(type) {
	case *ast.ExprStmt:
		a.walkExpr(t.X, env)
		return a.terminates(t)
	case *ast.AssignStmt:
		a.walkAssign(t, env)
	case *ast.DeclStmt:
		a.walkDecl(t, env)
	case *ast.IncDecStmt:
		if id, ok := t.X.(*ast.Ident); ok {
			env.invalidate(a.vkey(id))
