// and cursor, plus whether it printed a listing.
func (r *LineReader) doComplete(prompt string, buf []rune, pos int, again bool) ([]rune, int, bool) {
	cands, tokStart := r.complete(buf, pos)
	if len(cands) == 0 {
		return buf, pos, false
	}
