func (op *SigmoidOperation) Backward(grad *Tensor) error {
	if !op.Input.RequiresGrad {
		return nil
	}
	if op.Input.Grad == nil {
		op.Input.Grad = NewTensor(op.Input.Shape, make([]float32, len(op.Input.Data)), false)
