		sigmoidVal := float32(1.0 / (1.0 + math.Exp(-float64(op.Input.Data[i]))))
		op.Input.Grad.Data[i] += grad.Data[i] * sigmoidVal * (1 - sigmoidVal)
	}
	return nil
}
