func vecAddAccumulate(dst, src []float32) {
	n := len(dst)
	if n == 0 {
		return
	}
	_ = dst[n-1]
	_ = src[n-1]

	i := 0
	for ; i <= n-4; i += 4 {
		dst[i] += src[i]
		dst[i+1] += src[i+1]
		dst[i+2] += src[i+2]
		dst[i+3] += src[i+3]
	}
	for ; i < n; i++ {
		dst[i] += src[i]
