func loopAppendsTo(stmt ast.Stmt, name string) (ast.Expr, int) {
	fs, ok := stmt.(*ast.ForStmt)
	if !ok || fs.Init == nil || fs.Cond == nil || fs.Post == nil {
		return nil, 0
	}

