	end := fn.EndLine
	if end <= start {
		end = start + 1
	}
	if end-start > maxLines {
		end = start + maxLines
	}
	if end > len(lines) {
		end = len(lines)
	}
	out := strings.Join(lines[start:end], "\n")
	if fn.EndLine-start > maxLines {
